DO $stage$
DECLARE payload jsonb := $payload$[{"language": "es", "slug": "dip-de-charcuteria", "public_path": "/dip-de-charcuteria", "title": "Dip de charcutería con queso y salami, sin horno", "excerpt": "Prepara un dip de charcutería con queso, salami y verduras picadas. Sin horno, con aliño balsámico y fotos de cada paso para compartir.", "summary": "Todo lo que gusta de una tabla de quesos, picado para recogerlo con una galleta. Este dip lleva cheddar, mozzarella, salami y verduras frescas con un aliño ligero, sin mayonesa. Rinde 8 porciones de aperitivo; necesita 20 minutos de preparación y 10 de frío.", "content_html": "<h2>Sobre esta receta</h2><p>Todo lo que gusta de una tabla de quesos, picado para recogerlo con una galleta. Este dip lleva cheddar, mozzarella, salami y verduras frescas con un aliño ligero, sin mayonesa. Rinde 8 porciones de aperitivo; necesita 20 minutos de preparación y 10 de frío.</p>", "notes": "<h3>Consejos y conservación</h3><p>La mozzarella debe ser de baja humedad; la fresca necesita escurrirse muy bien y cambia la textura. Para una versión sin carne, sustituye el salami por garbanzos cocidos escurridos; cambia el sabor y la nutrición. Conserva tapado a 4 °C o menos y consume preferiblemente en 24 horas por textura. No dejes los perecederos fuera del frío más de 2 horas, o 1 hora si el ambiente supera 32 °C. Contiene leche; revisa los alérgenos del salami y del acompañamiento.</p><h3>Fuentes</h3><ul><li><a href=\"https://www.foodandwine.com/charcuterie-dip-trend-12186744\">Food &amp; Wine — charcuterie dip trend, 22 October 2026</a></li><li><a href=\"https://www.fda.gov/food/buy-store-serve-safe-food/manipulacion-segura-de-los-alimentos-lo-que-usted-debe-saber\">FDA — safe food handling</a></li></ul><p><a href=\"https://fdc.nal.usda.gov/\">USDA FoodData Central</a></p>", "ingredients": [{"name": "tomates cherry", "amount": "200", "unit": "g"}, {"name": "pepino, peso limpio sin semillas acuosas", "amount": "150", "unit": "g"}, {"name": "queso cheddar", "amount": "100", "unit": "g"}, {"name": "queso mozzarella de baja humedad", "amount": "100", "unit": "g"}, {"name": "salami listo para consumir", "amount": "100", "unit": "g"}, {"name": "aceitunas verdes sin hueso, escurridas", "amount": "60", "unit": "g"}, {"name": "aceite de oliva", "amount": "20", "unit": "g"}, {"name": "vinagre balsámico", "amount": "15", "unit": "g"}, {"name": "albahaca fresca", "amount": "5", "unit": "g"}, {"name": "pimienta negra molida", "amount": "0.5", "unit": "g"}], "steps": [{"title": "Lava y seca las verduras", "content": "Lava los tomates y el pepino bajo agua corriente. Sécalos bien para que el aliño no termine aguado. Usa un recipiente limpio y amplio.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-01.webp", "image_alt": "Lava y seca las verduras — Dip de charcutería con queso y salami, sin horno"}, {"title": "Pica las verduras", "content": "Corta los tomates y el pepino en trozos de unos 6 mm. Retira el centro del pepino si suelta mucha agua; pesa la cantidad limpia indicada.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-02.webp", "image_alt": "Pica las verduras — Dip de charcutería con queso y salami, sin horno"}, {"title": "Corta quesos y salami", "content": "Pica el cheddar, la mozzarella y el salami en dados pequeños. El tamaño parejo permite recoger todos los sabores en cada bocado.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-03.webp", "image_alt": "Corta quesos y salami — Dip de charcutería con queso y salami, sin horno"}, {"title": "Prepara el aliño", "content": "Escurre y pica las aceitunas. Bate el aceite, el vinagre balsámico y la pimienta en un recipiente pequeño hasta que se mezclen.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-04.webp", "image_alt": "Prepara el aliño — Dip de charcutería con queso y salami, sin horno"}, {"title": "Mezcla la base", "content": "Reúne verduras, quesos, salami y aceitunas en el bol. Añade el aliño y remueve desde el fondo, sin aplastar el tomate.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-05.webp", "image_alt": "Mezcla la base — Dip de charcutería con queso y salami, sin horno"}, {"title": "Termina con albahaca", "content": "Corta la albahaca en tiras finas y mézclala con el dip. Prueba antes de añadir sal: los quesos, el salami y las aceitunas ya aportan bastante.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-06.webp?v=2392b67a", "image_alt": "Termina con albahaca — Dip de charcutería con queso y salami, sin horno"}, {"title": "Enfría brevemente", "content": "Tapa y refrigera durante 10 minutos a 4 °C o menos. Si vas a servirlo después, conserva las verduras y el aliño separados hasta el final.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-07.webp", "image_alt": "Enfría brevemente — Dip de charcutería con queso y salami, sin horno"}, {"title": "Sirve para compartir", "content": "Remueve una vez y sirve frío con una cuchara. Puedes acompañarlo con galletas o pan tostado, que no están incluidos en la lista ni en el cálculo nutricional.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-08.webp", "image_alt": "Sirve para compartir — Dip de charcutería con queso y salami, sin horno"}], "category": "Entrantes y aperitivos", "course": "Entradas", "cuisine": "Internacional", "difficulty": "Fácil", "prep_time_minutes": 20, "cook_time_minutes": 0, "total_time_minutes": 30, "servings": 8, "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/dip-de-charcuteria/portada.webp", "alt": "Dip picado de quesos, salami, tomate, pepino y aceitunas con albahaca"}], "video_urls": [], "keywords": ["dip de charcutería", "charcuterie dip", "aperitivo sin horno", "dip de queso y salami"], "nutrition": {"calories": 180.5, "protein_g": 8.8, "carbs_g": 3.0, "fat_g": 15.0, "estimated": true, "serving_size": "1 de 8 porciones de aperitivo, aproximadamente 94 g", "note": "Estimación por ración; los productos y el rendimiento pueden cambiar los valores.", "source": "USDA FoodData Central, SR Legacy; ten ingredient profiles retrieved 2026-11-04", "method": "Sum edible weights × USDA SR Legacy per-100-g nutrients / 8 servings. FDC identifiers and calculations saved in editorial source. Crackers excluded.", "source_url": "https://fdc.nal.usda.gov/"}, "seo": {"title": "Dip de charcutería con queso y salami, sin horno", "description": "Prepara un dip de charcutería con queso, salami y verduras picadas. Sin horno, con aliño balsámico y fotos de cada paso para compartir.", "author": "Néstor Bastidas", "image_alt": "Dip picado de quesos, salami, tomate, pepino y aceitunas con albahaca", "image_variants": ["https://manualdecocina.com/recetas/dip-de-charcuteria/portada-1x1.webp", "https://manualdecocina.com/recetas/dip-de-charcuteria/portada-4x3.webp", "https://manualdecocina.com/recetas/dip-de-charcuteria/portada-16x9.webp"], "faq": [{"q": "¿Es un dip cremoso?", "a": "No. Es una mezcla picada y aliñada, parecida a una tabla de charcutería servida en un bol."}, {"q": "¿Se puede preparar el día anterior?", "a": "Sí, pero guarda las verduras secas y el aliño separados. Combina y añade la albahaca poco antes de servir para conservar la textura."}, {"q": "¿Hace falta añadir sal?", "a": "Prueba primero. Los quesos, las aceitunas y el salami suelen aportar suficiente; esta formulación no lleva sal añadida."}], "additional_time_minutes": 10}, "published": false, "editorial_status": "draft"}, {"language": "en", "slug": "charcuterie-dip", "public_path": "/en/charcuterie-dip", "title": "Charcuterie Dip with Cheese and Salami, No Baking", "excerpt": "Make chopped charcuterie dip with cheese, salami and fresh vegetables. A no-bake appetizer with balsamic dressing and step-by-step photos.", "summary": "The flavors of a cheese board, chopped small enough to scoop onto a cracker. Cheddar, mozzarella, salami and fresh vegetables get a light dressing without mayonnaise. Makes 8 appetizer servings with 20 minutes of preparation and 10 minutes of chilling.", "content_html": "<h2>About this recipe</h2><p>The flavors of a cheese board, chopped small enough to scoop onto a cracker. Cheddar, mozzarella, salami and fresh vegetables get a light dressing without mayonnaise. Makes 8 appetizer servings with 20 minutes of preparation and 10 minutes of chilling.</p>", "notes": "<h3>Tips and storage</h3><p>Use low-moisture mozzarella; fresh mozzarella needs thorough draining and changes the texture. For a meat-free variation, replace salami with drained cooked chickpeas; flavor and nutrition change. Keep covered at 4 °C / 40 °F or below and preferably eat within 24 hours for texture. Limit time out of refrigeration to 2 hours, or 1 hour above 32 °C / 90 °F. Contains milk; check salami and accompaniment allergen labels.</p><h3>Sources</h3><ul><li><a href=\"https://www.foodandwine.com/charcuterie-dip-trend-12186744\">Food &amp; Wine — charcuterie dip trend, 22 October 2026</a></li><li><a href=\"https://www.fda.gov/food/buy-store-serve-safe-food/manipulacion-segura-de-los-alimentos-lo-que-usted-debe-saber\">FDA — safe food handling</a></li></ul><p><a href=\"https://fdc.nal.usda.gov/\">USDA FoodData Central</a></p>", "ingredients": [{"name": "cherry tomatoes", "amount": "200", "unit": "g"}, {"name": "cucumber, trimmed weight without watery seeds", "amount": "150", "unit": "g"}, {"name": "cheddar cheese", "amount": "100", "unit": "g"}, {"name": "low-moisture mozzarella", "amount": "100", "unit": "g"}, {"name": "ready-to-eat salami", "amount": "100", "unit": "g"}, {"name": "pitted green olives, drained", "amount": "60", "unit": "g"}, {"name": "olive oil", "amount": "20", "unit": "g"}, {"name": "balsamic vinegar", "amount": "15", "unit": "g"}, {"name": "fresh basil", "amount": "5", "unit": "g"}, {"name": "ground black pepper", "amount": "0.5", "unit": "g"}], "steps": [{"title": "Wash and dry the vegetables", "content": "Rinse the tomatoes and cucumber under running water. Dry thoroughly so the dressing stays flavorful rather than watery. Use a clean, roomy bowl.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-01.webp", "image_alt": "Wash and dry the vegetables — Charcuterie Dip with Cheese and Salami, No Baking"}, {"title": "Chop the vegetables", "content": "Cut the tomatoes and cucumber into roughly 6 mm pieces. Remove a watery cucumber seed core and weigh the prepared cucumber amount listed.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-02.webp", "image_alt": "Chop the vegetables — Charcuterie Dip with Cheese and Salami, No Baking"}, {"title": "Dice the cheese and salami", "content": "Cut the cheddar, mozzarella and salami into small pieces. Even chopping lets each spoonful carry a little of every ingredient.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-03.webp", "image_alt": "Dice the cheese and salami — Charcuterie Dip with Cheese and Salami, No Baking"}, {"title": "Mix the dressing", "content": "Drain and chop the olives. Whisk the olive oil, balsamic vinegar and black pepper together in a small bowl.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-04.webp", "image_alt": "Mix the dressing — Charcuterie Dip with Cheese and Salami, No Baking"}, {"title": "Combine the base", "content": "Put the vegetables, cheeses, salami and olives in the bowl. Add the dressing and fold gently from the bottom without crushing the tomatoes.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-05.webp", "image_alt": "Combine the base — Charcuterie Dip with Cheese and Salami, No Baking"}, {"title": "Add the basil", "content": "Slice the basil thinly and fold it through. Taste before adding salt: the cheeses, salami and olives already provide plenty.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-06.webp?v=2392b67a", "image_alt": "Add the basil — Charcuterie Dip with Cheese and Salami, No Baking"}, {"title": "Chill briefly", "content": "Cover and refrigerate for 10 minutes at 4 °C / 40 °F or below. For later serving, keep vegetables and dressing separate until needed.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-07.webp", "image_alt": "Chill briefly — Charcuterie Dip with Cheese and Salami, No Baking"}, {"title": "Serve to share", "content": "Stir once and serve cold with a spoon. Crackers or toasted bread are optional accompaniments, excluded from the ingredient list and nutrition estimate.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-08.webp", "image_alt": "Serve to share — Charcuterie Dip with Cheese and Salami, No Baking"}], "category": "Starters & appetizers", "course": "Appetizers", "cuisine": "International", "difficulty": "Easy", "prep_time_minutes": 20, "cook_time_minutes": 0, "total_time_minutes": 30, "servings": 8, "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/dip-de-charcuteria/portada.webp", "alt": "Chopped cheese and salami dip with tomato, cucumber, green olives and basil"}], "video_urls": [], "keywords": ["charcuterie dip", "chopped cheese dip", "no bake appetizer", "salami dip"], "nutrition": {"calories": 180.5, "protein_g": 8.8, "carbs_g": 3.0, "fat_g": 15.0, "estimated": true, "serving_size": "1 of 8 appetizer servings, about 94 g", "note": "Estimated per serving; products and yield can change these values.", "source": "USDA FoodData Central, SR Legacy; ten ingredient profiles retrieved 2026-11-04", "method": "Sum edible weights × USDA SR Legacy per-100-g nutrients / 8 servings. FDC identifiers and calculations saved in editorial source. Crackers excluded.", "source_url": "https://fdc.nal.usda.gov/"}, "seo": {"title": "Charcuterie Dip with Cheese and Salami, No Baking", "description": "Make chopped charcuterie dip with cheese, salami and fresh vegetables. A no-bake appetizer with balsamic dressing and step-by-step photos.", "author": "Néstor Bastidas", "image_alt": "Chopped cheese and salami dip with tomato, cucumber, green olives and basil", "image_variants": ["https://manualdecocina.com/recetas/dip-de-charcuteria/portada-1x1.webp", "https://manualdecocina.com/recetas/dip-de-charcuteria/portada-4x3.webp", "https://manualdecocina.com/recetas/dip-de-charcuteria/portada-16x9.webp"], "faq": [{"q": "Is this a creamy dip?", "a": "No. It is a chopped, dressed mixture, like a charcuterie board served in a bowl."}, {"q": "Can I make it a day ahead?", "a": "Keep the dry prepared vegetables and dressing separate, then combine and add basil shortly before serving."}, {"q": "Does it need added salt?", "a": "Taste first. The cheeses, olives and salami usually supply enough; this recipe has no added salt."}], "additional_time_minutes": 10}, "published": false, "editorial_status": "draft"}, {"language": "de", "slug": "charcuterie-dip-kaese-salami", "public_path": "/de/charcuterie-dip-kaese-salami", "title": "Charcuterie-Dip mit Käse und Salami ohne Backen", "excerpt": "Käse, Salami und frisches Gemüse als fein gewürfelter Charcuterie-Dip. Mit Balsamico-Dressing und Schrittbildern, ganz ohne Backofen.", "summary": "Die Aromen einer Käseplatte, so klein geschnitten, dass sie auf einen Cracker passen. Cheddar, Mozzarella, Salami und Gemüse werden mit einem leichten Dressing ohne Mayonnaise vermengt. Ergibt 8 Vorspeisenportionen; 20 Minuten Vorbereitung und 10 Minuten Kühlzeit.", "content_html": "<h2>Über dieses Rezept</h2><p>Die Aromen einer Käseplatte, so klein geschnitten, dass sie auf einen Cracker passen. Cheddar, Mozzarella, Salami und Gemüse werden mit einem leichten Dressing ohne Mayonnaise vermengt. Ergibt 8 Vorspeisenportionen; 20 Minuten Vorbereitung und 10 Minuten Kühlzeit.</p>", "notes": "<h3>Tipps und Aufbewahrung</h3><p>Schnittfesten Mozzarella verwenden; frischer Mozzarella muss gut abtropfen und verändert die Konsistenz. Salami lässt sich für eine fleischfreie Variante durch abgetropfte gekochte Kichererbsen ersetzen; Geschmack und Nährwerte ändern sich. Abgedeckt bei höchstens 4 °C lagern und für gute Konsistenz möglichst innerhalb von 24 Stunden essen. Höchstens 2 Stunden ungekühlt stehen lassen, bei über 32 °C nur 1 Stunde. Enthält Milch; Allergene von Salami und Beilagen prüfen.</p><h3>Quellen</h3><ul><li><a href=\"https://www.foodandwine.com/charcuterie-dip-trend-12186744\">Food &amp; Wine — charcuterie dip trend, 22 October 2026</a></li><li><a href=\"https://www.fda.gov/food/buy-store-serve-safe-food/manipulacion-segura-de-los-alimentos-lo-que-usted-debe-saber\">FDA — safe food handling</a></li></ul><p><a href=\"https://fdc.nal.usda.gov/\">USDA FoodData Central</a></p>", "ingredients": [{"name": "Kirschtomaten", "amount": "200", "unit": "g"}, {"name": "Gurke, geputzt und ohne wässrige Kerne gewogen", "amount": "150", "unit": "g"}, {"name": "Cheddar", "amount": "100", "unit": "g"}, {"name": "schnittfester Mozzarella", "amount": "100", "unit": "g"}, {"name": "verzehrfertige Salami", "amount": "100", "unit": "g"}, {"name": "grüne Oliven ohne Stein, abgetropft", "amount": "60", "unit": "g"}, {"name": "Olivenöl", "amount": "20", "unit": "g"}, {"name": "Balsamico-Essig", "amount": "15", "unit": "g"}, {"name": "frisches Basilikum", "amount": "5", "unit": "g"}, {"name": "gemahlener schwarzer Pfeffer", "amount": "0.5", "unit": "g"}], "steps": [{"title": "Gemüse waschen und trocknen", "content": "Tomaten und Gurke unter fließendem Wasser waschen. Gründlich trocknen, damit das Dressing nicht verwässert. Eine saubere, ausreichend große Schüssel bereitstellen.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-01.webp", "image_alt": "Gemüse waschen und trocknen — Charcuterie-Dip mit Käse und Salami ohne Backen"}, {"title": "Gemüse klein schneiden", "content": "Tomaten und Gurke in etwa 6 mm große Stücke schneiden. Einen wässrigen Gurkenkern entfernen und die angegebene Menge geputzte Gurke abwiegen.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-02.webp", "image_alt": "Gemüse klein schneiden — Charcuterie-Dip mit Käse und Salami ohne Backen"}, {"title": "Käse und Salami würfeln", "content": "Cheddar, Mozzarella und Salami klein schneiden. Gleichmäßige Stücke sorgen dafür, dass jeder Löffel verschiedene Zutaten enthält.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-03.webp", "image_alt": "Käse und Salami würfeln — Charcuterie-Dip mit Käse und Salami ohne Backen"}, {"title": "Dressing verrühren", "content": "Oliven abtropfen lassen und hacken. Öl, Balsamico und Pfeffer in einer kleinen Schüssel mit einem Schneebesen verrühren.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-04.webp", "image_alt": "Dressing verrühren — Charcuterie-Dip mit Käse und Salami ohne Backen"}, {"title": "Zutaten vermengen", "content": "Gemüse, Käse, Salami und Oliven in die Schüssel geben. Dressing zufügen und vorsichtig von unten mischen, ohne die Tomaten zu zerdrücken.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-05.webp", "image_alt": "Zutaten vermengen — Charcuterie-Dip mit Käse und Salami ohne Backen"}, {"title": "Basilikum zufügen", "content": "Basilikum in feine Streifen schneiden und unterheben. Vor dem Salzen probieren: Käse, Salami und Oliven bringen bereits viel Salz mit.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-06.webp?v=2392b67a", "image_alt": "Basilikum zufügen — Charcuterie-Dip mit Käse und Salami ohne Backen"}, {"title": "Kurz kühlen", "content": "Abgedeckt 10 Minuten bei höchstens 4 °C kühlen. Bei späterem Servieren Gemüse und Dressing bis zum Mischen getrennt aufbewahren.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-07.webp", "image_alt": "Kurz kühlen — Charcuterie-Dip mit Käse und Salami ohne Backen"}, {"title": "Gemeinsam genießen", "content": "Einmal durchrühren und kalt mit einem Löffel servieren. Cracker oder geröstetes Brot sind optionale Beilagen und nicht in Zutatenliste oder Nährwertschätzung enthalten.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-08.webp", "image_alt": "Gemeinsam genießen — Charcuterie-Dip mit Käse und Salami ohne Backen"}], "category": "Vorspeisen", "course": "Vorspeisen", "cuisine": "International", "difficulty": "Einfach", "prep_time_minutes": 20, "cook_time_minutes": 0, "total_time_minutes": 30, "servings": 8, "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/dip-de-charcuteria/portada.webp", "alt": "Fein gewürfelter Dip aus Käse, Salami, Tomaten, Gurke und Oliven mit Basilikum"}], "video_urls": [], "keywords": ["Charcuterie Dip", "Käse Salami Dip", "Vorspeise ohne Backen", "Partydip"], "nutrition": {"calories": 180.5, "protein_g": 8.8, "carbs_g": 3.0, "fat_g": 15.0, "estimated": true, "serving_size": "1 von 8 Vorspeisenportionen, etwa 94 g", "note": "Schätzwerte pro Portion; Produkte und Ausbeute können die Werte verändern.", "source": "USDA FoodData Central, SR Legacy; ten ingredient profiles retrieved 2026-11-04", "method": "Sum edible weights × USDA SR Legacy per-100-g nutrients / 8 servings. FDC identifiers and calculations saved in editorial source. Crackers excluded.", "source_url": "https://fdc.nal.usda.gov/"}, "seo": {"title": "Charcuterie-Dip mit Käse und Salami ohne Backen", "description": "Käse, Salami und frisches Gemüse als fein gewürfelter Charcuterie-Dip. Mit Balsamico-Dressing und Schrittbildern, ganz ohne Backofen.", "author": "Néstor Bastidas", "image_alt": "Fein gewürfelter Dip aus Käse, Salami, Tomaten, Gurke und Oliven mit Basilikum", "image_variants": ["https://manualdecocina.com/recetas/dip-de-charcuteria/portada-1x1.webp", "https://manualdecocina.com/recetas/dip-de-charcuteria/portada-4x3.webp", "https://manualdecocina.com/recetas/dip-de-charcuteria/portada-16x9.webp"], "faq": [{"q": "Ist dieser Dip cremig?", "a": "Nein, er besteht aus klein geschnittenen, angemachten Zutaten, ähnlich einer Käseplatte in einer Schüssel."}, {"q": "Kann ich ihn am Vortag vorbereiten?", "a": "Trockenes vorbereitetes Gemüse und Dressing getrennt kühlen. Erst kurz vor dem Servieren mischen und Basilikum zufügen."}, {"q": "Braucht der Dip Salz?", "a": "Erst probieren. Käse, Oliven und Salami reichen meist aus; das Rezept enthält kein zusätzliches Salz."}], "additional_time_minutes": 10}, "published": false, "editorial_status": "draft"}, {"language": "fr", "slug": "dip-charcuterie-fromage-salami", "public_path": "/fr/dip-charcuterie-fromage-salami", "title": "Dip de charcuterie au fromage et salami sans cuisson", "excerpt": "Un dip de charcuterie haché avec fromage, salami et légumes frais. Vinaigrette balsamique, sans cuisson et photos de chaque étape.", "summary": "Les saveurs d’une planche de fromages, coupées assez finement pour garnir un cracker. Cheddar, mozzarella, salami et légumes sont liés par une vinaigrette légère, sans mayonnaise. Pour 8 portions apéritives : 20 minutes de préparation et 10 minutes au frais.", "content_html": "<h2>À propos de cette recette</h2><p>Les saveurs d’une planche de fromages, coupées assez finement pour garnir un cracker. Cheddar, mozzarella, salami et légumes sont liés par une vinaigrette légère, sans mayonnaise. Pour 8 portions apéritives : 20 minutes de préparation et 10 minutes au frais.</p>", "notes": "<h3>Conseils et conservation</h3><p>Choisissez une mozzarella à faible humidité ; la mozzarella fraîche doit être bien égouttée et modifie la texture. Pour une variante sans viande, remplacez le salami par des pois chiches cuits égouttés ; goût et nutrition changent. Gardez couvert à 4 °C maximum et consommez de préférence sous 24 heures pour la texture. Ne laissez pas hors du froid plus de 2 heures, ou 1 heure au-dessus de 32 °C. Contient du lait ; vérifiez les allergènes du salami et des accompagnements.</p><h3>Sources</h3><ul><li><a href=\"https://www.foodandwine.com/charcuterie-dip-trend-12186744\">Food &amp; Wine — charcuterie dip trend, 22 October 2026</a></li><li><a href=\"https://www.fda.gov/food/buy-store-serve-safe-food/manipulacion-segura-de-los-alimentos-lo-que-usted-debe-saber\">FDA — safe food handling</a></li></ul><p><a href=\"https://fdc.nal.usda.gov/\">USDA FoodData Central</a></p>", "ingredients": [{"name": "tomates cerises", "amount": "200", "unit": "g"}, {"name": "concombre, poids net sans graines aqueuses", "amount": "150", "unit": "g"}, {"name": "cheddar", "amount": "100", "unit": "g"}, {"name": "mozzarella à faible humidité", "amount": "100", "unit": "g"}, {"name": "salami prêt à consommer", "amount": "100", "unit": "g"}, {"name": "olives vertes dénoyautées et égouttées", "amount": "60", "unit": "g"}, {"name": "huile d’olive", "amount": "20", "unit": "g"}, {"name": "vinaigre balsamique", "amount": "15", "unit": "g"}, {"name": "basilic frais", "amount": "5", "unit": "g"}, {"name": "poivre noir moulu", "amount": "0.5", "unit": "g"}], "steps": [{"title": "Lavez et séchez les légumes", "content": "Rincez tomates et concombre sous l’eau courante. Séchez soigneusement pour éviter une vinaigrette diluée. Préparez un grand saladier propre.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-01.webp", "image_alt": "Lavez et séchez les légumes — Dip de charcuterie au fromage et salami sans cuisson"}, {"title": "Coupez les légumes", "content": "Coupez tomates et concombre en morceaux d’environ 6 mm. Retirez le cœur du concombre s’il est aqueux et pesez la quantité nette indiquée.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-02.webp", "image_alt": "Coupez les légumes — Dip de charcuterie au fromage et salami sans cuisson"}, {"title": "Détaillez fromages et salami", "content": "Coupez cheddar, mozzarella et salami en petits dés réguliers. Chaque cuillerée pourra ainsi réunir plusieurs saveurs.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-03.webp", "image_alt": "Détaillez fromages et salami — Dip de charcuterie au fromage et salami sans cuisson"}, {"title": "Préparez la vinaigrette", "content": "Égouttez et hachez les olives. Fouettez huile, vinaigre balsamique et poivre dans un petit bol.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-04.webp", "image_alt": "Préparez la vinaigrette — Dip de charcuterie au fromage et salami sans cuisson"}, {"title": "Mélangez la base", "content": "Réunissez légumes, fromages, salami et olives dans le saladier. Ajoutez la vinaigrette et soulevez délicatement sans écraser les tomates.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-05.webp", "image_alt": "Mélangez la base — Dip de charcuterie au fromage et salami sans cuisson"}, {"title": "Ajoutez le basilic", "content": "Émincez le basilic et incorporez-le. Goûtez avant de saler : fromages, salami et olives sont déjà bien salés.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-06.webp?v=2392b67a", "image_alt": "Ajoutez le basilic — Dip de charcuterie au fromage et salami sans cuisson"}, {"title": "Réfrigérez brièvement", "content": "Couvrez et placez 10 minutes à 4 °C maximum. Pour servir plus tard, gardez légumes et vinaigrette séparés jusqu’au dernier moment.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-07.webp", "image_alt": "Réfrigérez brièvement — Dip de charcuterie au fromage et salami sans cuisson"}, {"title": "Servez à partager", "content": "Remuez une fois et servez froid avec une cuillère. Crackers et pain grillé sont facultatifs et exclus de la liste et de l’estimation nutritionnelle.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-08.webp", "image_alt": "Servez à partager — Dip de charcuterie au fromage et salami sans cuisson"}], "category": "Entrées et apéritifs", "course": "Entrées", "cuisine": "Internationale", "difficulty": "Facile", "prep_time_minutes": 20, "cook_time_minutes": 0, "total_time_minutes": 30, "servings": 8, "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/dip-de-charcuteria/portada.webp", "alt": "Dip haché de fromages, salami, tomates, concombre et olives au basilic"}], "video_urls": [], "keywords": ["dip de charcuterie", "dip fromage salami", "apéritif sans cuisson", "charcuterie dip"], "nutrition": {"calories": 180.5, "protein_g": 8.8, "carbs_g": 3.0, "fat_g": 15.0, "estimated": true, "serving_size": "1 des 8 portions apéritives, environ 94 g", "note": "Estimation par portion ; les produits et le rendement peuvent modifier ces valeurs.", "source": "USDA FoodData Central, SR Legacy; ten ingredient profiles retrieved 2026-11-04", "method": "Sum edible weights × USDA SR Legacy per-100-g nutrients / 8 servings. FDC identifiers and calculations saved in editorial source. Crackers excluded.", "source_url": "https://fdc.nal.usda.gov/"}, "seo": {"title": "Dip de charcuterie au fromage et salami sans cuisson", "description": "Un dip de charcuterie haché avec fromage, salami et légumes frais. Vinaigrette balsamique, sans cuisson et photos de chaque étape.", "author": "Néstor Bastidas", "image_alt": "Dip haché de fromages, salami, tomates, concombre et olives au basilic", "image_variants": ["https://manualdecocina.com/recetas/dip-de-charcuteria/portada-1x1.webp", "https://manualdecocina.com/recetas/dip-de-charcuteria/portada-4x3.webp", "https://manualdecocina.com/recetas/dip-de-charcuteria/portada-16x9.webp"], "faq": [{"q": "Est-ce un dip crémeux ?", "a": "Non, c’est un mélange finement coupé et assaisonné, comme une planche de charcuterie servie en saladier."}, {"q": "Peut-on le préparer la veille ?", "a": "Gardez les légumes secs et la vinaigrette séparés au frais. Mélangez et ajoutez le basilic juste avant de servir."}, {"q": "Faut-il ajouter du sel ?", "a": "Goûtez d’abord : fromages, olives et salami suffisent souvent. Cette recette ne contient pas de sel ajouté."}], "additional_time_minutes": 10}, "published": false, "editorial_status": "draft"}, {"language": "it", "slug": "dip-salumi-formaggi-salame", "public_path": "/it/dip-salumi-formaggi-salame", "title": "Dip di salumi e formaggi con salame, senza cottura", "excerpt": "Un dip a pezzetti con formaggi, salame e verdure fresche. Condimento al balsamico, nessuna cottura e foto di tutti i passaggi.", "summary": "I sapori di un tagliere, tagliati abbastanza piccoli da raccogliere con un cracker. Cheddar, mozzarella, salame e verdure hanno un condimento leggero senza maionese. Per 8 porzioni da aperitivo: 20 minuti di preparazione e 10 minuti in frigorifero.", "content_html": "<h2>Informazioni sulla ricetta</h2><p>I sapori di un tagliere, tagliati abbastanza piccoli da raccogliere con un cracker. Cheddar, mozzarella, salame e verdure hanno un condimento leggero senza maionese. Per 8 porzioni da aperitivo: 20 minuti di preparazione e 10 minuti in frigorifero.</p>", "notes": "<h3>Consigli e conservazione</h3><p>Usa mozzarella a bassa umidità; quella fresca va scolata bene e modifica la consistenza. Per una variante senza carne, sostituisci il salame con ceci cotti scolati; cambiano gusto e valori nutrizionali. Conserva coperto a non più di 4 °C e consuma preferibilmente entro 24 ore per la consistenza. Non lasciare fuori frigo oltre 2 ore, o 1 ora sopra 32 °C. Contiene latte; controlla gli allergeni di salame e accompagnamenti.</p><h3>Fonti</h3><ul><li><a href=\"https://www.foodandwine.com/charcuterie-dip-trend-12186744\">Food &amp; Wine — charcuterie dip trend, 22 October 2026</a></li><li><a href=\"https://www.fda.gov/food/buy-store-serve-safe-food/manipulacion-segura-de-los-alimentos-lo-que-usted-debe-saber\">FDA — safe food handling</a></li></ul><p><a href=\"https://fdc.nal.usda.gov/\">USDA FoodData Central</a></p>", "ingredients": [{"name": "pomodorini", "amount": "200", "unit": "g"}, {"name": "cetriolo, peso pulito senza semi acquosi", "amount": "150", "unit": "g"}, {"name": "cheddar", "amount": "100", "unit": "g"}, {"name": "mozzarella a bassa umidità", "amount": "100", "unit": "g"}, {"name": "salame pronto al consumo", "amount": "100", "unit": "g"}, {"name": "olive verdi denocciolate e scolate", "amount": "60", "unit": "g"}, {"name": "olio d’oliva", "amount": "20", "unit": "g"}, {"name": "aceto balsamico", "amount": "15", "unit": "g"}, {"name": "basilico fresco", "amount": "5", "unit": "g"}, {"name": "pepe nero macinato", "amount": "0.5", "unit": "g"}], "steps": [{"title": "Lava e asciuga le verdure", "content": "Sciacqua pomodorini e cetriolo sotto acqua corrente. Asciuga bene per non annacquare il condimento. Prepara una ciotola ampia e pulita.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-01.webp", "image_alt": "Lava e asciuga le verdure — Dip di salumi e formaggi con salame, senza cottura"}, {"title": "Taglia le verdure", "content": "Riduci pomodorini e cetriolo in pezzi di circa 6 mm. Elimina il cuore acquoso del cetriolo e pesa la quantità pulita indicata.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-02.webp", "image_alt": "Taglia le verdure — Dip di salumi e formaggi con salame, senza cottura"}, {"title": "Taglia formaggi e salame", "content": "Taglia cheddar, mozzarella e salame a dadini piccoli e regolari. Ogni cucchiaiata raccoglierà così un po’ di tutti gli ingredienti.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-03.webp", "image_alt": "Taglia formaggi e salame — Dip di salumi e formaggi con salame, senza cottura"}, {"title": "Prepara il condimento", "content": "Scola e trita le olive. Sbatti olio, aceto balsamico e pepe in una ciotolina.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-04.webp", "image_alt": "Prepara il condimento — Dip di salumi e formaggi con salame, senza cottura"}, {"title": "Mescola la base", "content": "Riunisci verdure, formaggi, salame e olive nella ciotola. Versa il condimento e mescola dal basso senza schiacciare i pomodorini.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-05.webp", "image_alt": "Mescola la base — Dip di salumi e formaggi con salame, senza cottura"}, {"title": "Aggiungi il basilico", "content": "Taglia il basilico a striscioline e incorporalo. Assaggia prima di salare: formaggi, salame e olive sono già saporiti.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-06.webp?v=2392b67a", "image_alt": "Aggiungi il basilico — Dip di salumi e formaggi con salame, senza cottura"}, {"title": "Raffredda brevemente", "content": "Copri e lascia 10 minuti in frigorifero a non più di 4 °C. Se servi dopo, conserva verdure e condimento separati fino all’ultimo.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-07.webp", "image_alt": "Raffredda brevemente — Dip di salumi e formaggi con salame, senza cottura"}, {"title": "Servi da condividere", "content": "Mescola una volta e servi freddo con un cucchiaio. Cracker e pane tostato sono accompagnamenti facoltativi, esclusi dagli ingredienti e dalla stima nutrizionale.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-08.webp", "image_alt": "Servi da condividere — Dip di salumi e formaggi con salame, senza cottura"}], "category": "Antipasti", "course": "Antipasti", "cuisine": "Internazionale", "difficulty": "Facile", "prep_time_minutes": 20, "cook_time_minutes": 0, "total_time_minutes": 30, "servings": 8, "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/dip-de-charcuteria/portada.webp", "alt": "Dip a pezzetti con formaggi, salame, pomodorini, cetriolo, olive e basilico"}], "video_urls": [], "keywords": ["dip salumi e formaggi", "dip salame", "aperitivo senza cottura", "charcuterie dip"], "nutrition": {"calories": 180.5, "protein_g": 8.8, "carbs_g": 3.0, "fat_g": 15.0, "estimated": true, "serving_size": "1 di 8 porzioni da aperitivo, circa 94 g", "note": "Stima per porzione; prodotti e resa possono modificare questi valori.", "source": "USDA FoodData Central, SR Legacy; ten ingredient profiles retrieved 2026-11-04", "method": "Sum edible weights × USDA SR Legacy per-100-g nutrients / 8 servings. FDC identifiers and calculations saved in editorial source. Crackers excluded.", "source_url": "https://fdc.nal.usda.gov/"}, "seo": {"title": "Dip di salumi e formaggi con salame, senza cottura", "description": "Un dip a pezzetti con formaggi, salame e verdure fresche. Condimento al balsamico, nessuna cottura e foto di tutti i passaggi.", "author": "Néstor Bastidas", "image_alt": "Dip a pezzetti con formaggi, salame, pomodorini, cetriolo, olive e basilico", "image_variants": ["https://manualdecocina.com/recetas/dip-de-charcuteria/portada-1x1.webp", "https://manualdecocina.com/recetas/dip-de-charcuteria/portada-4x3.webp", "https://manualdecocina.com/recetas/dip-de-charcuteria/portada-16x9.webp"], "faq": [{"q": "È un dip cremoso?", "a": "No, è un insieme di ingredienti tagliati piccoli e conditi, come un tagliere servito in ciotola."}, {"q": "Si può preparare il giorno prima?", "a": "Conserva verdure asciutte e condimento separati in frigorifero. Mescola e unisci il basilico poco prima di servire."}, {"q": "Serve aggiungere sale?", "a": "Assaggia prima. Formaggi, olive e salame di solito bastano; la ricetta non prevede sale aggiunto."}], "additional_time_minutes": 10}, "published": false, "editorial_status": "draft"}, {"language": "ja", "slug": "cheese-salami-charcuterie-dip", "public_path": "/ja/cheese-salami-charcuterie-dip", "title": "チーズとサラミのシャルキュトリーディップ｜火を使わない前菜", "excerpt": "チーズ、サラミ、きゅうり、トマトを細かく刻むシャルキュトリーディップ。バルサミコのドレッシングで仕上げる、写真付きの前菜レシピです。", "summary": "チーズの盛り合わせを、クラッカーですくいやすい小さな具にした前菜です。チェダー、モッツァレラ、サラミと野菜を、マヨネーズを使わない軽いドレッシングで和えます。前菜8人分。下準備20分、冷やす時間10分です。", "content_html": "<h2>このレシピについて</h2><p>チーズの盛り合わせを、クラッカーですくいやすい小さな具にした前菜です。チェダー、モッツァレラ、サラミと野菜を、マヨネーズを使わない軽いドレッシングで和えます。前菜8人分。下準備20分、冷やす時間10分です。</p>", "notes": "<h3>コツと保存方法</h3><p>低水分のモッツァレラを使います。フレッシュタイプは十分な水切りが必要で、食感も変わります。肉を使わない場合はサラミを水切りしたゆでひよこ豆に替えられますが、味と栄養値は変わります。ふたをして4 °C以下で保存し、食感のためできれば24時間以内に食べます。常温に置く時間は2時間以内、32 °Cを超える場合は1時間以内にします。乳を含みます。サラミや添え物のアレルゲン表示も確認してください。</p><h3>参考資料</h3><ul><li><a href=\"https://www.foodandwine.com/charcuterie-dip-trend-12186744\">Food &amp; Wine — charcuterie dip trend, 22 October 2026</a></li><li><a href=\"https://www.fda.gov/food/buy-store-serve-safe-food/manipulacion-segura-de-los-alimentos-lo-que-usted-debe-saber\">FDA — safe food handling</a></li></ul><p><a href=\"https://fdc.nal.usda.gov/\">USDA FoodData Central</a></p>", "ingredients": [{"name": "ミニトマト", "amount": "200", "unit": "g"}, {"name": "きゅうり（水っぽい種を除いた正味量）", "amount": "150", "unit": "g"}, {"name": "チェダーチーズ", "amount": "100", "unit": "g"}, {"name": "低水分タイプのモッツァレラチーズ", "amount": "100", "unit": "g"}, {"name": "そのまま食べられるサラミ", "amount": "100", "unit": "g"}, {"name": "種なしグリーンオリーブ（水切り後）", "amount": "60", "unit": "g"}, {"name": "オリーブオイル", "amount": "20", "unit": "g"}, {"name": "バルサミコ酢", "amount": "15", "unit": "g"}, {"name": "生バジル", "amount": "5", "unit": "g"}, {"name": "黒こしょう", "amount": "0.5", "unit": "g"}], "steps": [{"title": "野菜を洗って乾かす", "content": "トマトときゅうりを流水で洗い、水気をしっかり拭き取ります。水っぽくならないよう、清潔な大きめのボウルを用意します。", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-01.webp", "image_alt": "野菜を洗って乾かす — チーズとサラミのシャルキュトリーディップ｜火を使わない前菜"}, {"title": "野菜を刻む", "content": "トマトときゅうりを約6 mmに刻みます。きゅうりの中心が水っぽければ種を除き、材料欄の正味量を量ります。", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-02.webp", "image_alt": "野菜を刻む — チーズとサラミのシャルキュトリーディップ｜火を使わない前菜"}, {"title": "チーズとサラミを切る", "content": "チェダー、モッツァレラ、サラミを小さな角切りにします。大きさをそろえると、ひと口でいろいろな具を味わえます。", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-03.webp", "image_alt": "チーズとサラミを切る — チーズとサラミのシャルキュトリーディップ｜火を使わない前菜"}, {"title": "ドレッシングを作る", "content": "オリーブの水気を切って刻みます。小さな器でオイル、バルサミコ酢、こしょうをよく混ぜます。", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-04.webp", "image_alt": "ドレッシングを作る — チーズとサラミのシャルキュトリーディップ｜火を使わない前菜"}, {"title": "具を和える", "content": "ボウルに野菜、チーズ、サラミ、オリーブを入れます。ドレッシングを加え、トマトをつぶさないよう底から混ぜます。", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-05.webp", "image_alt": "具を和える — チーズとサラミのシャルキュトリーディップ｜火を使わない前菜"}, {"title": "バジルを加える", "content": "バジルを細切りにして混ぜます。チーズ、サラミ、オリーブに塩分があるので、塩を足す前に味を確認します。", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-06.webp?v=2392b67a", "image_alt": "バジルを加える — チーズとサラミのシャルキュトリーディップ｜火を使わない前菜"}, {"title": "短時間冷やす", "content": "ふたをして4 °C以下の冷蔵庫で10分冷やします。後で出す場合は、野菜とドレッシングを別々に保存して直前に和えます。", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-07.webp", "image_alt": "短時間冷やす — チーズとサラミのシャルキュトリーディップ｜火を使わない前菜"}, {"title": "盛り付ける", "content": "軽く混ぜ、冷たいままスプーンを添えて出します。クラッカーやトーストはお好みで添えますが、材料と栄養計算には含めていません。", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-08.webp", "image_alt": "盛り付ける — チーズとサラミのシャルキュトリーディップ｜火を使わない前菜"}], "category": "前菜・おつまみ", "course": "前菜", "cuisine": "インターナショナル", "difficulty": "簡単", "prep_time_minutes": 20, "cook_time_minutes": 0, "total_time_minutes": 30, "servings": 8, "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/dip-de-charcuteria/portada.webp", "alt": "チーズ、サラミ、トマト、きゅうり、オリーブとバジルの刻みディップ"}], "video_urls": [], "keywords": ["シャルキュトリーディップ", "チーズ サラミ 前菜", "火を使わないおつまみ", "charcuterie dip"], "nutrition": {"calories": 180.5, "protein_g": 8.8, "carbs_g": 3.0, "fat_g": 15.0, "estimated": true, "serving_size": "前菜8人分のうち1人分、約94 g", "note": "1人分の推定値です。使用する製品や出来上がり量によって変わります。", "source": "USDA FoodData Central, SR Legacy; ten ingredient profiles retrieved 2026-11-04", "method": "Sum edible weights × USDA SR Legacy per-100-g nutrients / 8 servings. FDC identifiers and calculations saved in editorial source. Crackers excluded.", "source_url": "https://fdc.nal.usda.gov/"}, "seo": {"title": "チーズとサラミのシャルキュトリーディップ｜火を使わない前菜", "description": "チーズ、サラミ、きゅうり、トマトを細かく刻むシャルキュトリーディップ。バルサミコのドレッシングで仕上げる、写真付きの前菜レシピです。", "author": "Néstor Bastidas", "image_alt": "チーズ、サラミ、トマト、きゅうり、オリーブとバジルの刻みディップ", "image_variants": ["https://manualdecocina.com/recetas/dip-de-charcuteria/portada-1x1.webp", "https://manualdecocina.com/recetas/dip-de-charcuteria/portada-4x3.webp", "https://manualdecocina.com/recetas/dip-de-charcuteria/portada-16x9.webp"], "faq": [{"q": "クリーミーなディップですか？", "a": "いいえ。具を細かく刻んで和えたもので、チーズやサラミの盛り合わせをボウルにまとめたような前菜です。"}, {"q": "前日に作れますか？", "a": "水気を切った野菜とドレッシングを別々に冷蔵し、食べる直前に和えてバジルを加えます。"}, {"q": "塩は必要ですか？", "a": "まず味を見てください。チーズ、オリーブ、サラミの塩分で足りることが多く、この配合では塩を加えません。"}], "additional_time_minutes": 10}, "published": false, "editorial_status": "draft"}, {"language": "pt", "slug": "dip-frios-queijos-salame", "public_path": "/pt/dip-frios-queijos-salame", "title": "Dip de frios com queijos e salame, sem forno", "excerpt": "Prepare um dip de frios picadinhos com queijos, salame e legumes frescos. Sem forno, com molho balsâmico e fotos de cada etapa.", "summary": "Os sabores de uma tábua de queijos, picados para caber numa torradinha. Cheddar, muçarela, salame e legumes recebem um molho leve, sem maionese. Rende 8 porções de aperitivo; são 20 minutos de preparo e 10 minutos na geladeira.", "content_html": "<h2>Sobre esta receita</h2><p>Os sabores de uma tábua de queijos, picados para caber numa torradinha. Cheddar, muçarela, salame e legumes recebem um molho leve, sem maionese. Rende 8 porções de aperitivo; são 20 minutos de preparo e 10 minutos na geladeira.</p>", "notes": "<h3>Dicas e conservação</h3><p>Use muçarela de baixa umidade; a fresca precisa escorrer bem e muda a textura. Para uma versão sem carne, troque o salame por grão-de-bico cozido escorrido; sabor e nutrição mudam. Guarde tampado a 4 °C ou menos e consuma de preferência em 24 horas para preservar a textura. Não deixe fora da geladeira por mais de 2 horas, ou 1 hora acima de 32 °C. Contém leite; confira os alérgenos do salame e dos acompanhamentos.</p><h3>Fontes</h3><ul><li><a href=\"https://www.foodandwine.com/charcuterie-dip-trend-12186744\">Food &amp; Wine — charcuterie dip trend, 22 October 2026</a></li><li><a href=\"https://www.fda.gov/food/buy-store-serve-safe-food/manipulacion-segura-de-los-alimentos-lo-que-usted-debe-saber\">FDA — safe food handling</a></li></ul><p><a href=\"https://fdc.nal.usda.gov/\">USDA FoodData Central</a></p>", "ingredients": [{"name": "tomates-cereja", "amount": "200", "unit": "g"}, {"name": "pepino, peso limpo sem sementes aquosas", "amount": "150", "unit": "g"}, {"name": "queijo cheddar", "amount": "100", "unit": "g"}, {"name": "muçarela de baixa umidade", "amount": "100", "unit": "g"}, {"name": "salame pronto para consumo", "amount": "100", "unit": "g"}, {"name": "azeitonas verdes sem caroço, escorridas", "amount": "60", "unit": "g"}, {"name": "azeite de oliva", "amount": "20", "unit": "g"}, {"name": "vinagre balsâmico", "amount": "15", "unit": "g"}, {"name": "manjericão fresco", "amount": "5", "unit": "g"}, {"name": "pimenta-do-reino moída", "amount": "0.5", "unit": "g"}], "steps": [{"title": "Lave e seque os legumes", "content": "Lave tomates e pepino em água corrente. Seque bem para o molho não ficar aguado. Separe uma tigela limpa e espaçosa.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-01.webp", "image_alt": "Lave e seque os legumes — Dip de frios com queijos e salame, sem forno"}, {"title": "Pique os legumes", "content": "Corte tomates e pepino em pedaços de cerca de 6 mm. Retire o miolo do pepino se estiver aguado e pese a quantidade limpa indicada.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-02.webp", "image_alt": "Pique os legumes — Dip de frios com queijos e salame, sem forno"}, {"title": "Corte queijos e salame", "content": "Pique cheddar, muçarela e salame em cubinhos pequenos. O tamanho uniforme ajuda a reunir todos os sabores em cada colherada.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-03.webp", "image_alt": "Corte queijos e salame — Dip de frios com queijos e salame, sem forno"}, {"title": "Prepare o molho", "content": "Escorra e pique as azeitonas. Bata azeite, vinagre balsâmico e pimenta numa tigelinha até misturar.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-04.webp", "image_alt": "Prepare o molho — Dip de frios com queijos e salame, sem forno"}, {"title": "Misture a base", "content": "Junte legumes, queijos, salame e azeitonas na tigela. Acrescente o molho e misture de baixo para cima, sem amassar os tomates.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-05.webp", "image_alt": "Misture a base — Dip de frios com queijos e salame, sem forno"}, {"title": "Finalize com manjericão", "content": "Corte o manjericão em tirinhas e incorpore. Prove antes de colocar sal: queijos, salame e azeitonas já são salgados.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-06.webp?v=2392b67a", "image_alt": "Finalize com manjericão — Dip de frios com queijos e salame, sem forno"}, {"title": "Leve à geladeira", "content": "Tampe e refrigere por 10 minutos a 4 °C ou menos. Para servir depois, mantenha legumes e molho separados até a hora de misturar.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-07.webp", "image_alt": "Leve à geladeira — Dip de frios com queijos e salame, sem forno"}, {"title": "Sirva para compartilhar", "content": "Misture uma vez e sirva frio com uma colher. Biscoitos salgados ou torradas são acompanhamentos opcionais, excluídos da lista e do cálculo nutricional.", "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/paso-08.webp", "image_alt": "Sirva para compartilhar — Dip de frios com queijos e salame, sem forno"}], "category": "Entradas e aperitivos", "course": "Entradas", "cuisine": "Internacional", "difficulty": "Fácil", "prep_time_minutes": 20, "cook_time_minutes": 0, "total_time_minutes": 30, "servings": 8, "image_url": "https://manualdecocina.com/recetas/dip-de-charcuteria/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/dip-de-charcuteria/portada.webp", "alt": "Dip picado de queijos, salame, tomate, pepino e azeitonas com manjericão"}], "video_urls": [], "keywords": ["dip de frios", "dip queijo salame", "aperitivo sem forno", "charcuterie dip"], "nutrition": {"calories": 180.5, "protein_g": 8.8, "carbs_g": 3.0, "fat_g": 15.0, "estimated": true, "serving_size": "1 de 8 porções de aperitivo, cerca de 94 g", "note": "Estimativa por porção; os produtos e o rendimento podem alterar os valores.", "source": "USDA FoodData Central, SR Legacy; ten ingredient profiles retrieved 2026-11-04", "method": "Sum edible weights × USDA SR Legacy per-100-g nutrients / 8 servings. FDC identifiers and calculations saved in editorial source. Crackers excluded.", "source_url": "https://fdc.nal.usda.gov/"}, "seo": {"title": "Dip de frios com queijos e salame, sem forno", "description": "Prepare um dip de frios picadinhos com queijos, salame e legumes frescos. Sem forno, com molho balsâmico e fotos de cada etapa.", "author": "Néstor Bastidas", "image_alt": "Dip picado de queijos, salame, tomate, pepino e azeitonas com manjericão", "image_variants": ["https://manualdecocina.com/recetas/dip-de-charcuteria/portada-1x1.webp", "https://manualdecocina.com/recetas/dip-de-charcuteria/portada-4x3.webp", "https://manualdecocina.com/recetas/dip-de-charcuteria/portada-16x9.webp"], "faq": [{"q": "É um dip cremoso?", "a": "Não. É uma mistura picadinha e temperada, como uma tábua de frios servida numa tigela."}, {"q": "Posso preparar no dia anterior?", "a": "Guarde legumes secos e molho separados na geladeira. Misture e acrescente o manjericão pouco antes de servir."}, {"q": "Precisa acrescentar sal?", "a": "Prove primeiro. Queijos, azeitonas e salame costumam bastar; esta receita não leva sal adicionado."}], "additional_time_minutes": 10}, "published": false, "editorial_status": "draft"}]$payload$::jsonb;
foods jsonb := $foods$[{"slug": "queso-cheddar", "name": "Queso cheddar", "description": "Queso cheddar en bloque, no salsa de queso."}, {"slug": "salami", "name": "Salami", "description": "Embutido curado listo para consumir; comprobar la etiqueta."}, {"slug": "aceitunas-verdes", "name": "Aceitunas verdes", "description": "Aceitunas verdes en conserva, sin hueso y escurridas."}, {"slug": "vinagre-balsamico", "name": "Vinagre balsámico", "description": "Vinagre balsámico, no crema ni reducción azucarada."}, {"slug": "albahaca-fresca", "name": "Albahaca fresca", "description": "Hojas frescas de albahaca para cocinar."}]$foods$::jsonb;
aliases jsonb := $aliases$[{"slug": "tomates-cherry", "alias": "tomates cherry"}, {"slug": "pepino", "alias": "pepino, peso limpio sin semillas acuosas"}, {"slug": "queso-cheddar", "alias": "queso cheddar"}, {"slug": "queso-mozzarella", "alias": "queso mozzarella de baja humedad"}, {"slug": "salami", "alias": "salami listo para consumir"}, {"slug": "aceitunas-verdes", "alias": "aceitunas verdes sin hueso, escurridas"}, {"slug": "aceite-de-oliva", "alias": "aceite de oliva"}, {"slug": "vinagre-balsamico", "alias": "vinagre balsámico"}, {"slug": "albahaca-fresca", "alias": "albahaca fresca"}, {"slug": "pimienta-negra", "alias": "pimienta negra molida"}]$aliases$::jsonb;
x jsonb; a jsonb; v public.recipes; made public.recipes; source_id uuid; group_id uuid;
BEGIN
PERFORM set_config('request.jwt.claim.sub','2caf0bab-d7e8-4d52-9910-d79799c27072',true);
IF NOT public.is_admin() THEN RAISE EXCEPTION 'Admin context missing'; END IF;
IF jsonb_array_length(payload)<>7 THEN RAISE EXCEPTION 'Need seven languages'; END IF;
IF EXISTS(SELECT 1 FROM public.recipes r JOIN jsonb_array_elements(payload) e ON r.public_path=e->>'public_path' OR (r.language=e->>'language' AND r.slug=e->>'slug')) THEN RAISE EXCEPTION 'Recipe URL already exists'; END IF;
IF EXISTS(SELECT 1 FROM public.content_pages p JOIN jsonb_array_elements(payload) e ON p.public_path=e->>'public_path') OR EXISTS(SELECT 1 FROM public.content_redirects r JOIN jsonb_array_elements(payload) e ON r.source_path=e->>'public_path') THEN RAISE EXCEPTION 'Route collision'; END IF;
FOR a IN SELECT value FROM jsonb_array_elements(foods) LOOP
 IF EXISTS(SELECT 1 FROM public.ingredients WHERE lower(name)=lower(a->>'name') AND slug<>a->>'slug' AND status='canonical') THEN RAISE EXCEPTION 'Canonical name collision'; END IF;
 INSERT INTO public.ingredients(slug,name,normalized_name,description,status,searchable,indexable)
 SELECT a->>'slug',a->>'name',lower(a->>'name'),a->>'description','canonical',true,false WHERE NOT EXISTS(SELECT 1 FROM public.ingredients WHERE slug=a->>'slug');
END LOOP;
FOR a IN SELECT value FROM jsonb_array_elements(aliases) LOOP
 IF NOT EXISTS(SELECT 1 FROM public.ingredients WHERE slug=a->>'slug' AND status='canonical') THEN RAISE EXCEPTION 'Missing canonical ingredient %',a; END IF;
 IF EXISTS(SELECT 1 FROM public.ingredient_aliases ia JOIN public.ingredients i ON i.id=ia.ingredient_id WHERE lower(trim(ia.alias))=lower(trim(a->>'alias')) AND i.slug<>a->>'slug' AND i.status='canonical') THEN RAISE EXCEPTION 'Alias collision %',a; END IF;
 INSERT INTO public.ingredient_aliases(ingredient_id,alias,normalized_alias) SELECT id,a->>'alias',lower(a->>'alias') FROM public.ingredients WHERE slug=a->>'slug' AND status='canonical' ON CONFLICT(ingredient_id,normalized_alias) DO NOTHING;
END LOOP;
FOR x IN SELECT value FROM jsonb_array_elements(payload) LOOP
 v:=jsonb_populate_record(NULL::public.recipes,x);
 IF v.language='es' THEN
  made:=public.create_recipe(v.language,v.slug,v.title,v.excerpt,v.ingredients,v.steps,v.category,v.prep_time_minutes,v.cook_time_minutes,v.servings,v.image_url,false,v.public_path);
  source_id:=made.id;group_id:=made.recipe_group_id;
 ELSE
  made:=public.create_recipe_translation(source_id,v.language,v.slug,v.title,v.excerpt,v.ingredients,v.steps,v.category,v.prep_time_minutes,v.cook_time_minutes,v.servings,v.image_url,false,v.public_path);
 END IF;
 UPDATE public.recipes SET content_html=v.content_html,summary=v.summary,notes=v.notes,difficulty=v.difficulty,course=v.course,cuisine=v.cuisine,total_time_minutes=v.total_time_minutes,keywords=v.keywords,nutrition=v.nutrition,gallery=v.gallery,video_urls=v.video_urls,seo=v.seo,editorial_status='ready',ready_at=now() WHERE id=made.id;
END LOOP;
IF (SELECT count(*) FROM public.recipes WHERE recipe_group_id=group_id)<>7 THEN RAISE EXCEPTION 'Incomplete group'; END IF;
IF (SELECT count(*) FROM public.recipe_ingredients WHERE recipe_id=source_id)<>10 OR EXISTS(SELECT 1 FROM public.recipe_ingredient_pending WHERE recipe_id=source_id) THEN RAISE EXCEPTION 'Unresolved ingredients'; END IF;
END $stage$;
SELECT id,recipe_group_id,language,slug,published,editorial_status FROM public.recipes WHERE public_path IN ('/dip-de-charcuteria','/en/charcuterie-dip','/de/charcuterie-dip-kaese-salami','/fr/dip-charcuterie-fromage-salami','/it/dip-salumi-formaggi-salame','/ja/cheese-salami-charcuterie-dip','/pt/dip-frios-queijos-salame') ORDER BY language;
